// 字符串转 __int128
inline void read128(__int128 &x){
    x=0;
    __int128 f=1;
    char ch = getchar();
    while (ch < '0' || ch > '9') {
        if (ch == '-') f = -1;
        ch = getchar();
    }
    while (ch >= '0' && ch <= '9') {
        x = x * 10 + ch - '0';
        ch = getchar();
    }
}
// __int128 转字符串（输出用）
void print128(__int128 x) {
    if (x < 0) {
        putchar('-');
        x = -x;
    }
    if (x > 9) print128(x / 10);
    putchar(x % 10 + '0');
}
int main() {
    // 读取 __int128
    __int128 a; read128(a);
    __int128 b; read128(b);
    // 运算（和普通整数一样）
    __int128 sum = a + b;
    __int128 product = a * b;
    // 输出
    cout << "Sum: ";
    print128(sum);
    cout << "Product: ";
    print128(product);
    return 0;
}
