# 01背包val_base

```c++
const ll INF=1e9;
ll w[110],v[110],sum=0,n,f[100010],ans=0,W;
int main(){
    cin>>n>>W;
    for(int i=1;i<=n;i++){
        cin>>w[i]>>v[i];
        sum+=v[i];
    }
    fill(f,f+100005,INF);
    f[0]=0;
    for(int i=1;i<=n;i++)
        for(int j=sum;j>=v[i];j--)
            if(f[j-v[i]]!=INF)
                f[j]=min(f[j],f[j-v[i]]+w[i]);

    for(int j=sum;j>=0;j--)
        if(f[j]<=W){
            ans=j;
            break;
        }
    cout<<ans<<endl;
}
```

# 01背包

```C++
ll N,W,w[200010],v[200010],ans[200010];
int main(){
    cin>>N>>W;
    for(int i=1;i<=N;i++)
        cin>>w[i]>>v[i];
    for(int i=1;i<=N;i++){
        for(int l=W;l>=w[i];l--){
            ans[l]=max(ans[l-w[i]]+v[i],ans[l]);
        }
    }
    cout<<ans[W]<<endl;
}
/*仔细观察代码可以发现：对于当前处理的物品 𝑖
i 和当前状态 𝑓𝑖,𝑗
f_{i,j}，在 𝑗 ⩾𝑤𝑖
j\geqslant w_{i} 时，𝑓𝑖,𝑗
f_{i,j} 是会被 𝑓𝑖,𝑗−𝑤𝑖
f_{i,j-w_{i}} 所影响的。这就相当于物品 𝑖
i 可以多次被放入背包，与题意不符。
（事实上，这正是完全背包问题的解法）*/
```

# 01bfs

```C++
const int INF = 0x3f3f3f3f;
const int MAXN = 1e5+1;
vector<pair<int, int>> graph[MAXN];
int main(){
    int n, m, source;
    deque<int> dq;
    vector<int> dist(n, INF);
    dist[source] = 0;
    dq.push_front(source);
    while (!dq.empty()) {
        int u = dq.front(); dq.pop_front();
        for (auto [v, w] : graph[u]) {
            if (w == 0 && dist[v] > dist[u]) {
                dist[v] = dist[u];
                dq.push_front(v);  // 边权0，加入前端
            } else if (w == 1 && dist[v] > dist[u] + 1) {
                dist[v] = dist[u] + 1;
                dq.push_back(v);   // 边权1，加入后端
            }
        }
    }
}
```

# 单调队列

```C++
int h=0,t=-1,q[1000010],n,a[1000010];
int main(){
    ll n,m; cin>>n>>m;
    for(int i=1;i<=n;i++) cin>>a[i];
    for(int i=1;i<=n;i++){
        if(h<=t && q[h]<i-m+1) h++;
        while(h<=t && a[i]<=a[q[t]]) t--;
        q[++t]=i;
        if(i>m-1) printf("%d ",a[q[h]]);
    }
    cout<<endl;
}
/*对只除去开头元素来保证不过期的解释：
新的大元素会淘汰所有旧元素，
清空后新元素下标最大，确保不会漏掉过期检查
队列下标的**单调递增**保证了过期检测的简单性
使用方式：可以用于配合求区间最值，如区间和，
加上前缀和，减掉最小位置就行了*/
```

