# 区间dp

```C++
ll n,a[410],ans[410][410],sum[410];
int main(){
    cin>>n;
    memset(ans,0x3f,sizeof(ans));
    for(int i=1;i<=n;i++){
        cin>>a[i];
        sum[i]=sum[i-1]+a[i];
        ans[i][i]=0;
    }
    for(int l=2;l<=n;l++){
        for(int i=1;i+l-1<=n;i++){
            ll j=i+l-1;
            for(int k=i;k<j;k++){
                ans[i][j]=min(ans[i][k]+ans[k+1][j]+sum[j]-sum[i-1],ans[i][j]);
            }
        }
    }
    cout<<ans[1][n]<<endl;
}
/*首先，每个区间自己合并的代价是0，
之后枚举长度，枚举起点，计算每个区间的值，
记得加上区间的总值，即合并后所需的代价。*/
```

# 拓扑排序

```C++
const ll MAXN=200010;
ll n, m;
vector<ll> G[MAXN];
ll in[MAXN];  // 存储每个结点的入度
bool toposort() {
    vector<ll> L;
    queue<ll> S;
    for (int i = 1; i <= n; i++)
        if (in[i] == 0) S.push(i);
    while (!S.empty()) {
        int u = S.front();
        S.pop();
        L.push_back(u);
        for (auto v : G[u]) {
            if (--in[v] == 0) {
                S.push(v);
            }
        }
    }
    if (L.size() == n) {
        for (auto i : L) cout << i << ' ';
        return true;
    }
    return false;
}
```

# 依赖背包

```C++
ll n,v[65],w[65],f[65][32010],V;
vector<ll> a[65];
void dfs(ll now){
    for(int i=v[now];i<=V;i++)
        f[now][i]=v[now];
    for(auto &s:a[now]){
        dfs(s);
        for(int j=V;j>=v[now];j--)
            for(int k=v[s];k+v[now]<=j;k++)
                f[now][j]=max(f[now][j],f[now][j-k]+f[s][k]);
    }
}
int main(){
    cin>>V>>n;
    for(int i=1;i<=n;i++){
        ll f; cin>>v[i]>>w[i]>>f;
        a[f].push_back(i);
    }
    dfs(0);
    cout<<f[0][V]<<endl;
}
/*循环时，从根往上计算，外层遍历体积，内层为决策，
看选择子树体积为k时是否合理来判断要不要选择。
f[i][j]表示选择i时体积为j的最大值*/
```

