```C++
const ll INF=1e18,N=1e5+10;
char s[N];
int ch[N][26],cnt[N],idx=0;
void insert(char *s){
    int p=0;
    for(int i=0;s[i];i++){
        int j=s[i]-'a';
        if(!ch[p][j]) ch[p][j]=++idx;
        p=ch[p][j];
    }
    cnt[p]++;
