        if(sum<0) sum=0;
    }
}
```

# dijkstra

```C++
long long N;
const long long INF=1e18;
vector<pair<LL,LL>> g[10010];
int main(){
    priority_queue<pair<LL, LL>, vector<pair<LL, LL>>, greater<pair<LL, LL>>> pq;vector<bool> vis(N+1, false);
    vector<LL> dis(N+1, INF);
    dis[1] = 0;
    pq.push({0, 1});
    while(!pq.empty()) {
        auto [d, u] = pq.top(); pq.pop();
        if(vis[u]) continue;
        vis[u] = true;
        for(auto [v, w] : g[u]) {
            if(!vis[v] && dis[v] > dis[u] + w) {
                dis[v] = dis[u] + w;
                pq.push({dis[v], v});
            }
        }
    }
}
```

# 交互题

```C++
int main(){
    int T; cin>>T;
    while(T--){
        ll n,y; cin>>n;
        ll sum=n*(n+1)/2;
        cout<<"2 1 "<<n<<endl;
        cout.flush();
        cin>>y;
        ll len=y-sum,l=1,r=n;
        while(l<=r){
            ll mid=(l+r)>>1;
            cout<<"1 1 "<<mid<<endl;
            cout.flush();
            ll last; cin>>last;
            cout<<"2 1 "<<mid<<endl;
            cout.flush();
            ll now; cin>>now;
            ll f=now-last;
