void isprime(int n){
  if(n==1){
    cout<<"No\"o"<<endl;
    return;
  }
  for(int i=2;i<=sqrt(n);i++){
    if(n%i==0){
      cout<<"No\"o"<<endl;
      return;
    }
  }
  cout<<"Yes"<<endl;
}
signed main()
  ll minn1=1e18,minn2=1e18,x;
  while(cin>>x){
    if(x<minn1){
      minn2=minn1;
      minn1=x;
    }
    else if(x<minn2)
      minn2=x;
  }
  isprime(minn2-minn1);
  return 0;
}
```


