  }
  for(int i=1;i<id;i++)
    if(a[i]!=a[id-i])
      return false;
  return true;
}
signed main(){
  ll x;
  while(cin>>x){
    x++;
    while(!hws(x++));
    cout<<x-1<<endl;
  }
}
```
这里因为要求要比x大，所以先x++，最后输出x-1的原因是循环里写的是x++最后会多1。

## F题
- 题目描述
如果一个数从左到右和从右到左读都一样，那么这个数就叫做“回文数”。如果一个数的十进制和二进制表示都是回文数，则把这个数叫做“双重回文数”。例如，十进制33是回文数，将其转化为二进制表示100001也是回文数，所以33是双重回文数。编写程序，查找1~1000的所有双重回文数。
- 解题思路
和上一题一样，只不过要多出力一个二进制的而已。
- 参考代码
```C++
bool hws(ll x){
  ll a[2000],id=1;
  ll y=x;
  while(x){
    a[id++]=x%10;
    x/=10;
  }
  for(int i=1;i<id;i++)
    if(a[i]!=a[id-i])
      return false;

  id=1;
  while(y){
    a[id++]=y%2;
    y/=2;
  }
  for(int i=1;i<id;i++)
    if(a[i]!=a[id-i])
      return false;
  return true;
}
signed main(){
  for(int i=1;i<=1000;i++)
    if(hws(i)) cout<<i<<"为双重回文数"<<endl;
}
```

